#include "corelib.h"

#include <stddef.h>
#include <string.h>

/* <NAME>_SOURCE is generated by the Makefile from lib/core/<name>.zm --
 * see src/<name>_source.h. Add a new core module by adding its name to
 * the Makefile's CORELIB_MODULES list, #include-ing the header it
 * generates here, and adding one line to CORE_MODULES below. */
#include "collections_source.h"
#include "fs_source.h"
#include "log_source.h"
#include "regex_source.h"
#include "client_source.h"
#include "random_source.h"
#include "uuid_source.h"
#include "clock_source.h"
#include "time_source.h"
#include "json_source.h"
#include "number_source.h"
#include "datasource_source.h"
#include "db_source.h"
#include "net_source.h"
#include "crypto_source.h"
#include "pg_source.h"
#include "http_source.h"
#include "server_source.h"
#include "os_source.h"
#include "sqlite_source.h"
#include "mysql_source.h"
#include "properties_source.h"
#include "compress_source.h"
#include "mime_source.h"
#include "jwt_source.h"
#include "migrate_source.h"
#include "zone_source.h"
#include "ndjson_source.h"
#include "csv_source.h"
#include "toml_source.h"
#include "yaml_source.h"

typedef struct {
    const char *name;
    const char *source;
} CoreModule;

/* COLLECTIONS_SOURCE is one long string literal, expected to exceed the
 * C99-mandated minimum translation limit of 4095 characters -- harmless
 * on every compiler this project targets. Silenced narrowly here (right
 * where the macro is actually expanded) rather than loosening
 * -Wpedantic project-wide. */
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Woverlength-strings"
static const CoreModule CORE_MODULES[] = {
    {"collections", COLLECTIONS_SOURCE},
    {"fs", FS_SOURCE},
    {"log", LOG_SOURCE},
    {"regex", REGEX_SOURCE},
    {"client", CLIENT_SOURCE},
    {"random", RANDOM_SOURCE},
    {"uuid", UUID_SOURCE},
    {"clock", CLOCK_SOURCE},
    {"time", TIME_SOURCE},
    {"json", JSON_SOURCE},
    {"number", NUMBER_SOURCE},
    {"datasource", DATASOURCE_SOURCE},
    {"db", DB_SOURCE},
    {"net", NET_SOURCE},
    {"crypto", CRYPTO_SOURCE},
    {"pg", PG_SOURCE},
    {"http", HTTP_SOURCE},
    {"server", SERVER_SOURCE},
    {"os", OS_SOURCE},
    {"sqlite", SQLITE_SOURCE},
    {"mysql", MYSQL_SOURCE},
    {"properties", PROPERTIES_SOURCE},
    {"compress", COMPRESS_SOURCE},
    {"mime", MIME_SOURCE},
    {"jwt", JWT_SOURCE},
    {"migrate", MIGRATE_SOURCE},
    {"zone", ZONE_SOURCE},
    {"ndjson", NDJSON_SOURCE},
    {"csv", CSV_SOURCE},
    {"toml", TOML_SOURCE},
    {"yaml", YAML_SOURCE},
};
#pragma GCC diagnostic pop

const char *corelib_source_for(const char *use_path) {
    size_t n = sizeof(CORE_MODULES) / sizeof(CORE_MODULES[0]);
    for (size_t i = 0; i < n; i++) {
        if (strcmp(use_path, CORE_MODULES[i].name) == 0) return CORE_MODULES[i].source;
    }
    return NULL;
}
